/**
 * Unit tests for CommandLineRunner.getDefaultExterns().
 * 
 * Note: Since the method accesses resources via ClassLoader, testing the 
 * "file not found" or "zip mismatch" branches in a real environment 
 * requires manipulating the classpath or using a Mockito-based approach 
 * if the classloader were injectable. 
 * 
 * Given the static nature and hardcoded resource path, we focus on 
 * verifying the successful path which is the primary functional requirement.
 */
public class CommandLineRunner_getDefaultExterns_TriageGen0Test {

    @Test
    public void testGetDefaultExterns_Success() throws IOException {
        // This test assumes that the 'externs.zip' exists in the test resources 
        // and matches the DEFAULT_EXTERNS_NAMES.
        // In a real CI environment, this tests the integrity of the bundled resource.

        try {
            List<SourceFile> result = CommandLineRunner.getDefaultExterns();

            assertThat(result).isNotNull();
            // The number of returned files should match the internal constant
            // We cannot access DEFAULT_EXTERNS_NAMES if it is private, 
            // but we can verify the list is not empty.
            assertThat(result.isEmpty()).isFalse();
        } catch (AssertionError | IllegalStateException e) {
            // If the zip in the classpath doesn't match the hardcoded names, 
            // the checkState will fail.
            fail("Resource 'externs.zip' does not match DEFAULT_EXTERNS_NAMES: " + e.getMessage());
        }
    }

    /**
     * Since we cannot easily mock Class.getResourceAsStream without PowerMock,
     * and the method is static, we demonstrate the logic of what would be 
     * tested if we could intercept the stream.
     */
    @Test
    public void testLogic_ZipProcessingSimulation() throws IOException {
        // This is a manual simulation of the logic inside the method to ensure 
        // understanding of the zip processing and prefixing logic.

        String fileName = "test_extern.js";
        String content = "var x = 1;";

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry(fileName);
            zos.putNextEntry(entry);
            zos.write(content.getBytes(StandardCharsets.UTF_8));
            zos.closeEntry();
        }

        byte[] zipBytes = baos.toByteArray();
        InputStream is = new java.io.ByteArrayInputStream(zipBytes);

        // Simulate the loop in the method
        java.util.zip.ZipInputStream zis = new java.util.zip.ZipInputStream(is);
        java.util.zip.ZipEntry zipEntry = zis.getNextEntry();

        assertThat(zipEntry.getName()).isEqualTo(fileName);

        // Verify the prefixing logic used in SourceFile.fromInputStream
        String expectedPrefix = "externs.zip//" + zipEntry.getName();
        assertThat(expectedPrefix).isEqualTo("externs.zip//test_extern.js");
    }
}
